#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m, n, maxHealth;
    cin >> m >> n >> maxHealth;
    vector<vector<int>> grid(m, vector<int>(n));
    int sx = -1, sy = -1;
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> grid[i][j];
            if (grid[i][j] == 3) sx = i, sy = j;
        }
    }

    vector<vector<int>> best(m, vector<int>(n, -1));
    queue<array<int, 4>> q;
    q.push({sx, sy, maxHealth, 0});
    best[sx][sy] = maxHealth;
    const int dx[4] = {1, -1, 0, 0};
    const int dy[4] = {0, 0, 1, -1};

    while (!q.empty()) {
        auto state = q.front();
        q.pop();
        int x = state[0], y = state[1], health = state[2], distance = state[3];
        if (grid[x][y] == 4) {
            cout << distance << '\n';
            return 0;
        }
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx < 0 || nx >= m || ny < 0 || ny >= n || grid[nx][ny] == 1) continue;
            int nextHealth = health;
            if (grid[nx][ny] == 2) --nextHealth;
            if (nextHealth <= 0) continue;
            if (grid[nx][ny] == 5) nextHealth = maxHealth;
            if (nextHealth <= best[nx][ny]) continue;
            best[nx][ny] = nextHealth;
            q.push({nx, ny, nextHealth, distance + 1});
        }
    }

    cout << -1 << '\n';
    return 0;
}

