#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<long long> work(n);
    long long low = 0, high = 0;
    for (long long& value : work) {
        cin >> value;
        low = max(low, value);
        high += value;
    }
    int k;
    cin >> k;

    auto needed = [&](long long limit) {
        int parts = 1;
        long long current = 0;
        for (long long value : work) {
            if (current + value > limit) {
                ++parts;
                current = 0;
            }
            current += value;
        }
        return parts;
    };

    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (needed(mid) <= k) high = mid;
        else low = mid + 1;
    }
    cout << low << '\n';
    return 0;
}

