#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<int> values;
    int value;
    while (cin >> value) values.push_back(value);
    int n = static_cast<int>(values.size());
    if (n < 2) {
        cout << 0 << '\n';
        return 0;
    }
    int total = accumulate(values.begin(), values.end(), 0);
    vector<vector<char>> dp(n + 1, vector<char>(total + 1, false));
    dp[0][0] = true;
    int used = 0;
    for (int x : values) {
        ++used;
        for (int count = used; count >= 1; --count) {
            for (int sum = total; sum >= x; --sum) {
                if (dp[count - 1][sum - x]) dp[count][sum] = true;
            }
        }
    }

    int answer = INT_MAX;
    for (int count = 1; count < n; ++count) {
        long long product = 1LL * count * total;
        if (product % n != 0) continue;
        int target = static_cast<int>(product / n);
        if (dp[count][target]) answer = min(answer, min(target, total - target));
    }
    if (answer == INT_MAX) cout << 0 << '\n';
    else cout << 1 << '\n' << answer << '\n';
    return 0;
}

