#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, minPoints;
    long long epsilon;
    cin >> n >> epsilon >> minPoints;
    vector<long long> x(n), y(n);
    for (int i = 0; i < n; ++i) cin >> x[i] >> y[i];

    vector<vector<char>> near(n, vector<char>(n, false));
    vector<int> count(n, 0);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            long long distance = llabs(x[i] - x[j]) + llabs(y[i] - y[j]);
            if (distance <= epsilon) {
                near[i][j] = true;
                ++count[i];
            }
        }
    }

    vector<char> core(n, false);
    for (int i = 0; i < n; ++i) core[i] = count[i] >= minPoints;
    for (int i = 0; i < n; ++i) {
        if (core[i]) {
            cout << 0 << '\n';
            continue;
        }
        bool border = false;
        for (int j = 0; j < n; ++j) {
            if (near[i][j] && core[j]) {
                border = true;
                break;
            }
        }
        cout << (border ? 1 : 2) << '\n';
    }
    return 0;
}

