#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;
    int n = static_cast<int>(s.size());
    vector<int> prefix(n, 0);
    for (int i = 1; i < n; ++i) {
        int j = prefix[i - 1];
        while (j > 0 && s[i] != s[j]) j = prefix[j - 1];
        if (s[i] == s[j]) ++j;
        prefix[i] = j;
    }
    int period = n - prefix[n - 1];
    if (n % period != 0) period = n;
    cout << s.substr(0, period) << ' ' << n / period << '\n';
    return 0;
}

