#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long radius;
    cin >> n >> radius;
    vector<long long> position(n);
    for (long long& x : position) cin >> x;
    sort(position.begin(), position.end());

    int answer = 0;
    int i = 0;
    while (i < n) {
        long long leftmost = position[i];
        int centerIndex = i;
        while (centerIndex + 1 < n && position[centerIndex + 1] <= leftmost + radius) {
            ++centerIndex;
        }
        long long coveredUntil = position[centerIndex] + radius;
        ++answer;
        while (i < n && position[i] <= coveredUntil) ++i;
    }
    cout << answer << '\n';
    return 0;
}

