#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n), crystal(m);
    for (long long& x : a) cin >> x;
    for (long long& x : crystal) cin >> x;

    using Slot = pair<long long, int>;  // {当前槽位代价, 法师编号}
    priority_queue<Slot, vector<Slot>, greater<Slot>> minHeap;
    for (int i = 0; i < n; ++i) minHeap.push({a[i], i});

    vector<long long> cheapestCosts;
    cheapestCosts.reserve(m);
    for (int count = 0; count < m; ++count) {
        auto [cost, wizard] = minHeap.top();
        minHeap.pop();
        cheapestCosts.push_back(cost);
        minHeap.push({cost + a[wizard], wizard});
    }

    sort(crystal.rbegin(), crystal.rend());

    long long answer = 0;
    for (int i = 0; i < m; ++i) {
        if (crystal[i] <= cheapestCosts[i]) break;
        answer += crystal[i] - cheapestCosts[i];
    }

    cout << answer << '\n';
    return 0;
}
